matched = set()
lines = []
for line in source.splitlines():
    for prefix, replacement in paragraphs.items():
        if line.strip().startswith("Paragraph '" + prefix):
            line = "    Paragraph '" + replacement.replace("'", "''") + "'"
            matched.add(prefix)
            break
    lines.append(line)
assert matched == set(paragraphs), set(paragraphs) - matched
source = '\n'.join(lines)
headings = {
    '1 Model details': '1 รายละเอียดโมเดล Model details',
    '2 Intended use': '2 ผู้ใช้และวิธีใช้ Intended use',
    '3 Factors': '3 กลุ่มที่ควรตรวจผล Factors',
    '4 Metrics': '4 เกณฑ์วัดผล Metrics',
    '5 Training data และ Evaluation data': '5 ข้อมูลที่ใช้สร้างและทดสอบโมเดล',
    '6 Quantitative analyses': '6 ผลการทดสอบ Quantitative analyses',
    '7 Explainability': '7 คำอธิบายคะแนน Explainability',
    '8 Ethical considerations': '8 ผลกระทบต่อผู้สมัคร Ethical considerations',
    '9 Caveats and recommendations': '9 ข้อจำกัดและคำแนะนำก่อนใช้',
}
for old, new in headings.items():
    source = source.replace("Heading '" + old + "'", "Heading '" + new + "'")
source = source.replace("('{0:N4}' -f [double]$model.cut)", "('{0:N2}%' -f (100*[double]$model.cut))")
source = source.replace("@('Outer fold','max depth','จำนวนต้นไม้','Threshold')", "@('รอบทดสอบ','ระดับต้นไม้','จำนวนต้นไม้','คะแนนเกณฑ์')")
