source = source.replace("@('กลุ่ม','n','FNR และ 95% CI','FPR และ 95% CI','เสนอทบทวน')", "@('กลุ่ม','จำนวน','พลาดผลรับ FNR','เสนอเกิน FPR','เสนอทบทวน')")
source = source.replace("@('กรณีและแถว CSV','ค่าฐาน → ค่าทำนาย','Threshold','ปัจจัยเด่น')", "@('กรณีและแถวข้อมูล','กลุ่มอ้างอิง → รายนี้','คะแนนเกณฑ์','ปัจจัยเพิ่มหรือลดคะแนน')")
source = source.replace("'FN แถว 1400'", "'พลาดผลรับ FN แถว 1400'").replace("'FP แถว 1011'", "'เสนอเกิน FP แถว 1011'")
source = source.replace('Interview +10.30, Skill −10.16, Experience −8.53', 'สัมภาษณ์ +10.30 ทักษะ −10.16 ประสบการณ์ −8.53')
source = source.replace('Interview −8.16, Education −6.78, Experience +3.08', 'สัมภาษณ์ −8.16 การศึกษา −6.78 ประสบการณ์ +3.08')
source = source.replace('HCD302_Model_Card_TH_Sarabun_New.docx', 'Model_Card_Readable.docx')
source = source.replace('model_card_sarabun.pdf', 'model_card_readable.pdf')
source = source.replace("'model_card_charts\\03_pfi.png'", "'tmp\\model_card_qa\\pfi_thai.png'")
